  ('valorant', 'Valorant', 'Riot Games', 'Tactical shooter 5v5', 'Akun Valorant dengan rank, koleksi skin, dan VP — semua dijual toko terverifikasi dan diserahkan lewat Rekber Room.', true, true, true, true, 'Riot ID', 'Contoh: NamaKamu#TAG — lihat di profil dalam game', null, null, 'from-rose-500/80 via-red-500/70 to-violet-600/80', 'VP', 1, '/images/Astra_--_TEASER_01.png'),
  ('mobile-legends', 'Mobile Legends', 'Moonton', 'MOBA 5v5 mobile', 'Akun Mobile Legends dengan rank, hero, dan skin — dijual toko terverifikasi dengan escrow dan proteksi pembeli.', true, true, false, true, 'User ID', 'Lihat di profil dalam game, contoh: 12345678', 'Zone ID', null, 'from-sky-500/80 via-blue-600/70 to-indigo-600/80', 'Diamond', 2, '/images/games/mobile-legends-1.png'),
  ('genshin-impact', 'Genshin Impact', 'HoYoverse', 'Open-world action RPG', 'Top-up Genesis Crystal Genshin Impact — proses instan, struk dikirim ke email dan WhatsApp.', false, true, false, false, 'UID', 'UID 9 digit — lihat di pojok kanan bawah layar game', 'Server', array['Asia', 'America', 'Europe', 'TW, HK, MO']::text[], 'from-amber-400/80 via-orange-500/70 to-emerald-500/70', 'Genesis Crystal', 3, null),
  ('free-fire', 'Free Fire', 'Garena', 'Battle royale mobile', 'Top-up Diamond Free Fire — proses instan, struk dikirim ke email dan WhatsApp.', false, true, false, false, 'Player ID', 'Lihat di profil dalam game', null, null, 'from-orange-500/80 via-amber-500/70 to-red-600/80', 'Diamond', 4, null);
