insert into public.stores (id, owner_id, slug, name, type, level, status, owner_legal_name, description, gradient, deposit_amount, deposit_status, identity_verified, rating, reviews, sold, followers, score_desc, score_attitude, score_delivery, reviewed_by, reviewed_at, created_at) values
  ('bbf2a2d3-5bef-4995-bbd8-cc6723c92202', '69dea42f-fa28-47c3-99d5-3c81c827a1f7', 'astralstore', 'AstralStore', 'OWNER', 'PLATINUM', 'ACTIVE', 'Pemilik AstralStore', 'Spesialis akun Valorant rank tinggi dengan koleksi skin langka. Semua akun milik sendiri, diinspeksi sebelum dijual.', 'from-violet-600/90 to-fuchsia-500/80', 500000, 'HELD', true, 4.94, 218, 231, 1240, 4.9, 4.9, 5, 'f7b4ed61-24ca-4a2f-8893-d4f46fcb0e4e', '2024-03-01T00:00:00Z'::timestamptz + interval '1 day', '2024-03-01T00:00:00Z'::timestamptz),
  ('c0f3cc00-f6de-4e22-a843-2005a01d52b5', '0cd138fb-eebf-404c-9727-a3ff739c8ab6', 'nusagame', 'NusaGame', 'RESELLER', 'VERIFIED', 'ACTIVE', 'Rizky Pratama', 'Reseller store dengan katalog terluas — akun titipan penjual eksternal yang dikurasi dan menjadi tanggung jawab penuh kami.', 'from-sky-600/90 to-cyan-500/80', 500000, 'HELD', true, 4.87, 395, 412, 2380, 4.8, 4.9, 4.8, 'f7b4ed61-24ca-4a2f-8893-d4f46fcb0e4e', '2023-11-01T00:00:00Z'::timestamptz + interval '1 day', '2023-11-01T00:00:00Z'::timestamptz),
  ('bc229cc5-5510-4035-b3d7-edc149e36dd0', '437416fd-304a-45c6-a0ca-0cc204a434b6', 'verdantshop', 'VerdantShop', 'OWNER', 'VERIFIED', 'ACTIVE', 'Pemilik VerdantShop', 'Akun Immortal+ pilihan dengan deskripsi detail. Fokus pada akurasi listing dan serah terima yang rapi.', 'from-emerald-600/90 to-teal-500/80', 500000, 'HELD', true, 4.91, 176, 189, 860, 4.9, 4.8, 4.7, 'f7b4ed61-24ca-4a2f-8893-d4f46fcb0e4e', '2024-06-01T00:00:00Z'::timestamptz + interval '1 day', '2024-06-01T00:00:00Z'::timestamptz),
  ('0811518d-4cbc-452f-bb7d-25aa1068b162', '3f815b0e-cdbe-47d2-bea4-86236f5ee4ce', 'gudangakun', 'GudangAkun', 'RESELLER', 'PLATINUM', 'ACTIVE', 'Pemilik GudangAkun', 'Toko volume terbesar di valostock.id. Ratusan akun terjual tiap bulan dengan pengiriman cepat.', 'from-amber-500/90 to-orange-500/80', 500000, 'HELD', true, 4.82, 702, 764, 3150, 4.7, 4.8, 4.9, 'f7b4ed61-24ca-4a2f-8893-d4f46fcb0e4e', '2023-01-01T00:00:00Z'::timestamptz + interval '1 day', '2023-01-01T00:00:00Z'::timestamptz),
  ('a100a6f0-f900-47fb-91c3-49b76b8f2320', 'f8f87deb-7743-4e19-b0cc-178f1d7575ef', 'skyvault', 'SkyVault', 'OWNER', 'AUTHORIZED', 'ACTIVE', 'Pemilik SkyVault', 'Toko baru dengan harga kompetitif. Sedang membangun rekam jejak — semua transaksi lewat escrow.', 'from-indigo-600/90 to-blue-500/80', 500000, 'HELD', true, 4.7, 88, 95, 310, 4.6, 4.7, 4.6, 'f7b4ed61-24ca-4a2f-8893-d4f46fcb0e4e', '2025-02-01T00:00:00Z'::timestamptz + interval '1 day', '2025-02-01T00:00:00Z'::timestamptz),
  ('743e9987-69ad-44b5-a7ba-0f2ab735b52f', '735fef3d-5f11-4bca-9fc3-93556512add2', 'tokobaru', 'TokoBaru', 'OWNER', 'AUTHORIZED', 'PENDING_REVIEW', 'Dimas Saputra', 'Toko demo yang menunggu verifikasi admin.', 'from-sky-500 to-indigo-600', 500000, 'HELD', false, 0, 0, 0, 0, 0, 0, 0, null, null, now() - interval '1 day'),
  ('5df3899e-5201-42cf-b4bf-7bc278190b75', 'a11db9e8-2f00-4e0d-9a05-4b1c81f3e29e', 'balastore', 'Bala Store', 'OWNER', 'AUTHORIZED', 'ACTIVE', 'Bala', 'Toko demo milik storebala@email.com — belum punya katalog.', 'from-violet-600 to-fuchsia-600', 500000, 'HELD', true, 0, 0, 0, 0, 0, 0, 0, 'f7b4ed61-24ca-4a2f-8893-d4f46fcb0e4e', now() - interval '1 day', now() - interval '2 days');
