insert into public.help_articles (slug, title, category, excerpt, body, popular, sort_order) values
  ('cara-membeli-akun', 'Cara membeli akun game di valostock.id', 'GETTING_STARTED', 'Dari mencari akun sampai serah terima di Rekber Room.', '[{"type":"list","items":["Cari akun lewat pencarian atau halaman game, lalu buka detailnya.","Beli langsung, atau nego dulu lewat tombol Tawar.","Bayar: harga akun + biaya penanganan (maks. 3,5%, min. Rp4.000) + proteksi Rp5.000. Dana ditahan di escrow.","Rekber Room terbuka — toko menyerahkan akun, kamu ganti email/password/2FA dan periksa isinya.","Tekan Selesai. Dana baru diteruskan ke toko setelah konfirmasimu, lalu beri rating."]},{"type":"paragraph","text":"Pembeli tidak perlu verifikasi identitas. Semua transaksi wajib di dalam platform — transaksi di luar menghilangkan escrow dan seluruh perlindunganmu."}]'::jsonb, true, 0),
  ('apa-itu-rekber-room', 'Apa itu Rekber Room dan kenapa serah terima harus di sana?', 'GETTING_STARTED', 'Ruang transaksi resmi yang diawasi admin dan tercatat.', '[{"type":"paragraph","text":"Rekber Room adalah ruang serah terima resmi yang terbuka otomatis setelah pembayaranmu terkonfirmasi. Kodenya sama dengan ID katalog (mis. VS001), diawasi admin, dan seluruh percakapan tersimpan sebagai bukti sengketa."},{"type":"paragraph","text":"Chat biasa hanya untuk tanya jawab — dilarang bertransaksi, bertukar email, atau nomor telepon di sana."}]'::jsonb, false, 1),
  ('cara-membuka-toko', 'Cara membuka toko (verifikasi + deposit)', 'BECOMING_STORE', 'Isi profil, deposit Rp500.000, lalu diverifikasi admin.', '[{"type":"list","items":["Daftar dengan email aktif, lalu buka menu Toko Saya (/sell).","Isi profil toko, nama pemilik sesuai KTP, dan pilih tipe: Owner Store (akun milik sendiri) atau Reseller Store (akun titipan penjual eksternal).","Bayar deposit keamanan Rp500.000 lewat Midtrans.","Admin memverifikasi identitas pemilik secara manual (gratis). Setelah disetujui, toko aktif dan bisa mulai listing."]},{"type":"paragraph","text":"Deposit adalah jaminan keamanan, bukan biaya layanan — bisa dikembalikan saat toko tutup dengan syarat akun bersih (lihat aturan toko)."}]'::jsonb, true, 2),
  ('tipe-toko-owner-reseller', 'Perbedaan Owner Store dan Reseller Store', 'BECOMING_STORE', 'Siapa yang bertanggung jawab atas akun yang dijual.', '[{"type":"paragraph","text":"Owner Store menjual akun miliknya sendiri. Reseller Store menjual akun titipan penjual eksternal — dan memikul tanggung jawab penuh atas identitas penjual, keaslian akun, dan kerugian pembeli. Platform hanya mengenal dan menindak toko: pembeli melapor dan menilai toko, bukan penjual eksternalnya."}]'::jsonb, false, 3),
  ('biaya-di-valostock', 'Rincian biaya: komisi, penanganan, dan proteksi', 'FEES_WITHDRAWAL', 'Tiga biaya sederhana — tanpa biaya posting atau biaya tersembunyi.', '[{"type":"list","items":["Komisi platform 5% dari harga final — dipotong dari toko saat pesanan selesai (Premium: 4,5% / 4%).","Biaya penanganan maks. 3,5% (min. Rp4.000) — dibayar pembeli saat checkout.","Proteksi Rp5.000 per pesanan — dibayar pembeli, jendela dukungan 14/30 hari.","Biaya penarikan toko Rp4.000 (+Rp2.500 pajak antarbank)."]},{"type":"paragraph","text":"Komisi selalu dihitung dari harga final setelah nego, jadi tawar-menawar tidak mengubah aturannya."}]'::jsonb, true, 4),
  ('penarikan-dana-toko', 'Penarikan dana toko & Account Validation', 'FEES_WITHDRAWAL', 'Nama rekening tujuan harus sama dengan nama pemilik toko yang terverifikasi.', '[{"type":"paragraph","text":"Dana toko tercatat di saldo toko (escrow → tersedia) dan tidak dipakai untuk operasional platform. Penarikan diproses setelah disetujui admin (transfer disimulasikan di prototype), dan hanya bisa ke rekening atas nama yang sama dengan nama pemilik toko yang terverifikasi (Account Validation). Nama tidak cocok → ditolak; mirip sebagian → ditinjau manual."},{"type":"paragraph","text":"Pencairan tersedia 5 jam setelah akun dinyatakan aman. Biaya penarikan Rp4.000 (+Rp2.500 pajak antarbank)."}]'::jsonb, false, 5),
  ('aturan-listing-akun', 'Aturan listing: kategori, deskripsi, dan ID katalog VS', 'BEFORE_SALE', 'Satu akun = satu katalog — tidak bisa dijual dua kali.', '[{"type":"paragraph","text":"Setiap listing mendapat ID katalog dari platform (awalan VS, mis. VS001). Satu akun hanya bisa punya satu katalog, sehingga double-sell tidak mungkin terjadi. Tulis deskripsi yang akurat: rank, skin/VP, region, akses email, dan metode serah terima."},{"type":"paragraph","text":"Toko juga bisa menjalankan Account Inspection (login-only, 2FA tetap di penjual) untuk mendapatkan badge Account Checked. Klaim mutlak seperti \"100% aman\" dilarang di seluruh platform."}]'::jsonb, false, 6),
  ('pesanan-selesai-dan-rating', 'Kapan pesanan dianggap selesai dan dana cair ke toko?', 'AFTER_SALE', 'Konfirmasi pembeli, jendela otomatis, dan rilis dana 5 jam.', '[{"type":"paragraph","text":"Pesanan selesai saat pembeli menekan Selesai setelah memeriksa akun, atau otomatis setelah jendela inspeksi berakhir jika pembeli tidak merespons. Dana (dikurangi komisi 5%) masuk ke saldo toko, dan pencairan tersedia 5 jam setelah akun dinyatakan aman."},{"type":"paragraph","text":"Setelah selesai, pembeli memberi rating keseluruhan plus Service Score tiga dimensi: akurasi deskripsi, sikap layanan, dan kecepatan pengiriman."}]'::jsonb, false, 7),
  ('cara-mengajukan-sengketa', 'Cara mengajukan sengketa (72 jam)', 'DISPUTES', 'Batas waktu, bukti yang dibutuhkan, dan arbitrase final.', '[{"type":"list","items":["Ajukan dalam 72 jam sejak masalah terjadi, lewat halaman pesanan (bukan chat).","Sertakan pernyataan lengkap + bukti: riwayat Rekber Room, tangkapan layar, bukti pengiriman.","Kedua pihak memberi tanggapan sesuai timeline yang bisa dipantau.","Jika tidak tercapai kesepakatan, platform mengarbitrase — keputusan final."]},{"type":"paragraph","text":"Toko yang terbukti bersalah menanggung refund pembeli, bisa ditambah potongan deposit. Klaim palsu dari pembeli menurunkan Buyer Trust Score."}]'::jsonb, true, 8),
  ('kebijakan-refund-top-up', 'Kebijakan refund top-up', 'TOPUP', 'Refund hanya jika item game tidak masuk — dikembalikan ke Balance.', '[{"type":"list","items":["Top-up yang berhasil (VP/diamond sudah masuk) tidak bisa direfund.","Jika item game tidak masuk ke akunmu, dana dikembalikan ke Balance (BLC) — bukan uang tunai.","Cek status pesananmu kapan saja di halaman Cek Invoice dengan nomor invoice.","Jika ada kendala, tim kami menghubungimu lewat email/WhatsApp yang kamu isi saat memesan."]},{"type":"paragraph","text":"Pastikan UID/ID player yang kamu masukkan benar — kesalahan pengisian UID di luar tanggung jawab platform."}]'::jsonb, true, 9),
  ('kenapa-balance-tidak-bisa-beli-akun', 'Kenapa Balance tidak bisa dipakai membeli akun?', 'BALANCE', 'Balance bersifat closed-loop: khusus top-up, demi tetap legal.', '[{"type":"paragraph","text":"Balance (BLC) adalah alat pembayaran internal khusus top-up, bukan uang elektronik. Agar tetap seperti itu secara hukum (tanpa lisensi e-money dari Bank Indonesia), Balance harus closed-loop:"},{"type":"list","items":["Hanya bisa dipakai untuk top-up game di valostock.id.","Tidak bisa dipakai membeli akun game.","Tidak bisa dicairkan ke bank atau e-wallet.","Tidak bisa ditransfer ke pengguna lain."]},{"type":"paragraph","text":"Jika batasan ini dilonggarkan, Balance berubah status menjadi uang elektronik yang butuh lisensi — karena itu aturan ini berlaku mutlak. Pembelian akun tetap menggunakan pembayaran reguler lewat escrow."}]'::jsonb, true, 10),
  ('sanksi-dan-penalti-toko', 'Sanksi bertingkat untuk pelanggaran toko', 'PENALTIES', 'Dari peringatan sampai blacklist perangkat/identitas/bank.', '[{"type":"paragraph","text":"Sanksi menyesuaikan tingkat pelanggaran: peringatan → pembatasan listing → denda dari deposit → suspensi 30 hari → ban permanen → blacklist (perangkat/identitas/bank) → proses hukum. Transaksi di luar platform, pengiriman palsu, dan listing bohong dikenai denda deposit + ban tanpa toleransi."}]'::jsonb, false, 11),
  ('tips-keamanan-akun', 'Tips keamanan setelah menerima akun', 'SECURITY', 'Langkah pertama yang wajib dilakukan di Rekber Room.', '[{"type":"list","items":["Ganti email akun ke email milikmu sendiri terlebih dahulu.","Ganti password dan aktifkan 2FA milikmu.","Periksa perangkat/sesi yang masih login dan keluarkan semuanya.","Lakukan semua ini sebelum menekan Selesai di Rekber Room."]},{"type":"paragraph","text":"Simpan bukti serah terima. Jika ada percobaan pengambilan kembali akun dalam masa proteksi (14/30 hari), laporkan segera dari halaman pesananmu."}]'::jsonb, false, 12);
insert into public.news_articles (slug, title, category, excerpt, cover, body, status, author_id, published_at, created_at) values
  ('valostock-resmi-dibuka', 'valostock.id Resmi Dibuka: Marketplace Akun Game dengan Escrow', 'Pengumuman', 'Jual beli akun Valorant kini lewat toko terverifikasi, dana ditahan di escrow sampai kamu mengonfirmasi akunnya aman.', '/images/products/1.jpeg', '[{"type":"paragraph","text":"Hari ini valostock.id resmi dibuka untuk publik. Kami membangun marketplace ini karena jual beli akun game selama ini berjalan lewat grup WhatsApp — lambat, rawan penipuan, dan tanpa jejak bukti. valostock.id memindahkan seluruh proses itu ke satu tempat yang tercatat dan diawasi."},{"type":"heading","text":"Hanya toko terverifikasi yang berjualan"},{"type":"paragraph","text":"Di valostock.id, penjual adalah Toko yang identitas pemiliknya sudah diverifikasi admin dan menyetor deposit keamanan Rp500.000. Pembeli tidak perlu verifikasi identitas — cukup daftar dan langsung belanja. Akuntabilitas terpusat di toko, dan itulah yang membuat sanksi bisa ditegakkan."},{"type":"heading","text":"Dana lewat escrow, bukan transfer langsung"},{"type":"paragraph","text":"Saat kamu membeli akun, dana ditahan di escrow dan baru diteruskan ke toko setelah kamu mengonfirmasi akun diterima dengan aman. Serah terima berlangsung di Rekber Room yang diawasi admin, sehingga setiap langkah tercatat sebagai bukti jika terjadi sengketa."},{"type":"image","src":"/images/products/2.jpeg","alt":"Marketplace valostock.id"},{"type":"paragraph","text":"Setiap pesanan juga dilengkapi proteksi pembeli dengan jendela dukungan 14 hari (akun ≤ Rp10 juta) atau 30 hari (akun > Rp10 juta). Selamat berbelanja — dan selamat datang di cara baru jual beli akun game."}]'::jsonb, 'PUBLISHED', 'aba098e4-9d38-40ec-89ed-85c59e566191', '2026-07-10T03:00:00Z'::timestamptz, '2026-07-10T03:00:00Z'::timestamptz),
  ('fitur-tawar-hadir', 'Fitur Tawar Kini Hadir: Nego Harga Langsung dengan Toko', 'Pembaruan Platform', 'Ajukan penawaran lewat tombol Tawar — toko bisa menerima, menolak, atau memberi harga balik sebelum penawaran kedaluwarsa.', '/images/products/3.jpeg', '[{"type":"paragraph","text":"Nego harga adalah bagian alami dari jual beli akun — dan sekarang kamu tidak perlu keluar platform untuk melakukannya. Fitur Tawar sudah aktif di semua halaman detail akun."},{"type":"heading","text":"Cara kerjanya"},{"type":"list","items":["Buka halaman akun yang kamu incar, lalu tekan tombol Tawar.","Isi harga penawaranmu dan kirim — setiap penawaran punya masa berlaku.","Toko bisa Menerima, Menolak, atau memberi Penawaran Balik.","Jika penawaran diterima, harga dan listing langsung terkunci untukmu."]},{"type":"paragraph","text":"Setelah harga terkunci, kamu tinggal melanjutkan ke pembayaran seperti biasa — dana tetap lewat escrow, dan komisi platform dihitung dari harga final yang disepakati. Ingin memastikan akun tidak diambil orang lain saat kamu berpikir? Gunakan Lock opsional Rp5.000 untuk mengunci akun selama 30 menit."},{"type":"paragraph","text":"Semua riwayat penawaran tersimpan di menu Penawaran Saya, jadi kamu selalu tahu status nego yang sedang berjalan."}]'::jsonb, 'PUBLISHED', 'aba098e4-9d38-40ec-89ed-85c59e566191', '2026-07-08T03:00:00Z'::timestamptz, '2026-07-08T03:00:00Z'::timestamptz),
  ('mengenal-badge-account-checked', 'Mengenal Badge Account Checked', 'Pembaruan Platform', 'Badge Account Checked menandai akun yang sudah diinspeksi tokonya dengan checklist, timestamp, dan bukti media.', '/images/products/4.jpeg', '[{"type":"paragraph","text":"Klaim tanpa bukti tidak berarti apa-apa. Karena itu kami tidak pernah memakai istilah seperti \"100% aman\" — sebagai gantinya, kami memberi toko cara untuk membuktikan kondisi akunnya lewat Account Inspection."},{"type":"heading","text":"Apa yang diperiksa"},{"type":"list","items":["Login berhasil tanpa kendala (login-only — email dan password tidak diubah).","Tidak ada pembatasan atau penalti aktif di akun.","Isi inventory dan rank sesuai dengan deskripsi listing.","2FA tetap aktif di tangan penjual sampai serah terima."]},{"type":"paragraph","text":"Seluruh proses direkam dengan checklist, timestamp, dan media (screenshot atau video) yang tersimpan di penyimpanan privat. Akun yang lolos mendapat badge Account Checked di halaman listingnya."},{"type":"image","src":"/images/products/5.jpeg","alt":"Contoh akun dengan badge Account Checked"},{"type":"paragraph","text":"Badge ini bersifat opsional bagi toko, tetapi akun dengan badge Account Checked cenderung lebih dipercaya pembeli. Cari ikonnya saat kamu menjelajah marketplace."}]'::jsonb, 'PUBLISHED', 'aba098e4-9d38-40ec-89ed-85c59e566191', '2026-07-05T03:00:00Z'::timestamptz, '2026-07-05T03:00:00Z'::timestamptz),
  ('cara-kerja-rekber-room', 'Cara Kerja Rekber Room: Serah Terima yang Diawasi Admin', 'Panduan', 'Setelah pembayaran masuk escrow, Rekber Room terbuka — di sinilah akun diserahkan, diperiksa, dan semua percakapan tercatat.', '/images/products/6.jpeg', '[{"type":"paragraph","text":"Rekber Room adalah ruang transaksi resmi di valostock.id. Begitu pembayaranmu terkonfirmasi dan dana tertahan di escrow, sistem otomatis membuka Rekber Room dengan kode ruangan sesuai ID katalog akun (misalnya VS001)."},{"type":"heading","text":"Langkah demi langkah"},{"type":"list","items":["Toko menyerahkan akses akun di dalam Rekber Room.","Kamu mengganti email, password, dan 2FA akun tersebut.","Periksa isi akun — rank, skin, dan detail lain sesuai listing.","Tekan Selesai. Dana baru diteruskan ke toko setelah konfirmasimu."]},{"type":"heading","text":"Kenapa harus di dalam platform?"},{"type":"paragraph","text":"Rekber Room diawasi admin dan seluruh percakapannya tersimpan. Jika terjadi sengketa, riwayat ruangan inilah yang menjadi bukti utama — sesuatu yang tidak kamu dapatkan saat bertransaksi lewat chat pribadi. Karena itu pula transaksi di luar platform melanggar aturan dan menghilangkan perlindunganmu."},{"type":"paragraph","text":"Chat biasa dengan toko tetap tersedia untuk tanya jawab, tetapi serah terima akun hanya terjadi di Rekber Room."}]'::jsonb, 'PUBLISHED', 'aba098e4-9d38-40ec-89ed-85c59e566191', '2026-07-03T03:00:00Z'::timestamptz, '2026-07-03T03:00:00Z'::timestamptz),
  ('flash-sale-juli', 'Flash Sale Juli: Diskon dari Toko Pilihan Sepanjang Bulan', 'Event & Promo', 'Toko-toko pilihan menggelar flash sale bergilir sepanjang Juli — pantau jadwalnya supaya tidak kehabisan.', '/images/products/7.jpeg', '[{"type":"paragraph","text":"Bulan ini toko-toko di valostock.id menggelar flash sale bergilir. Setiap periode berlangsung singkat dengan stok terbatas — akun yang masuk flash sale ditandai dengan label khusus dan harga coret di marketplace."},{"type":"heading","text":"Yang perlu kamu tahu"},{"type":"list","items":["Diskon ditentukan masing-masing toko, bukan oleh platform.","Harga flash sale otomatis berakhir saat periodenya habis.","Semua pembelian tetap lewat escrow dan proteksi pembeli seperti biasa.","Gabungkan dengan voucher toko untuk potongan tambahan jika tersedia."]},{"type":"paragraph","text":"Tambahkan akun incaranmu ke wishlist dan nyalakan notifikasi penurunan harga — kamu akan diberi tahu begitu akun tersebut masuk periode flash sale."}]'::jsonb, 'PUBLISHED', 'aba098e4-9d38-40ec-89ed-85c59e566191', '2026-07-01T03:00:00Z'::timestamptz, '2026-07-01T03:00:00Z'::timestamptz),
  ('vct-pacific-stage-2-dimulai', 'VCT Pacific Stage 2 Dimulai 16 Juli — Musim Ramai untuk Para Pemain', 'Esports', 'Panggung kompetitif kembali menyala. Ini artinya untuk kamu yang sedang berburu akun atau menaikkan rank musim ini.', '/images/products/8.jpeg', '[{"type":"paragraph","text":"VCT Pacific Stage 2 akan bergulir mulai 16 Juli. Seperti biasa, musim kompetitif besar selalu diikuti lonjakan aktivitas pemain — antrean ranked lebih ramai, dan permintaan akun dengan rank serta koleksi tertentu ikut naik."},{"type":"heading","text":"Dampaknya di marketplace"},{"type":"paragraph","text":"Berdasarkan pola musim sebelumnya, akun dengan rank Immortal ke atas dan akun dengan koleksi skin populer bergerak paling cepat selama periode turnamen. Jika kamu berencana membeli, memasang wishlist lebih awal membantu kamu memantau harga sebelum permintaan memuncak."},{"type":"paragraph","text":"Untuk para toko: pastikan deskripsi listing akurat dan pertimbangkan Account Inspection — pembeli baru yang datang dari hype turnamen cenderung memilih akun dengan badge Account Checked."},{"type":"paragraph","text":"Nonton bareng jalannya turnamen dan diskusi meta bisa kamu ikuti di kanal komunitas kami. Selamat menikmati musim kompetitif!"}]'::jsonb, 'PUBLISHED', 'aba098e4-9d38-40ec-89ed-85c59e566191', '2026-06-28T03:00:00Z'::timestamptz, '2026-06-28T03:00:00Z'::timestamptz),
  ('top-up-game-tersedia', 'Top-Up Game Kini Tersedia di valostock.id', 'Pengumuman', 'Isi VP dan kebutuhan game lain langsung dari valostock.id — bayar lewat QRIS, VA, e-wallet, retail, atau kartu kredit.', '/images/products/9.jpeg', '[{"type":"paragraph","text":"Selain marketplace akun, valostock.id kini melayani top-up game. Prosesnya instan: pilih game, masukkan UID, pilih nominal, isi kontak (email dan WhatsApp), lalu bayar dengan metode favoritmu."},{"type":"heading","text":"Fitur yang menyertainya"},{"type":"list","items":["Kode promo — masukkan saat checkout untuk potongan harga.","Struk dikirim otomatis ke email dan WhatsApp kamu.","Halaman Cek Invoice — lacak status top-up cukup dengan nomor invoice.","Top-Up Balance — saldo prabayar khusus top-up agar pembayaran lebih cepat."]},{"type":"heading","text":"Tentang Top-Up Balance"},{"type":"paragraph","text":"Balance bersifat closed-loop: hanya bisa dipakai untuk top-up game di valostock.id, tidak bisa ditarik tunai, tidak bisa dipakai membeli akun, dan tidak bisa ditransfer ke pengguna lain. Jika top-up gagal dan item tidak masuk, dana dikembalikan ke Balance. Aturan lengkapnya tersedia di pusat bantuan."}]'::jsonb, 'PUBLISHED', 'aba098e4-9d38-40ec-89ed-85c59e566191', '2026-06-25T03:00:00Z'::timestamptz, '2026-06-25T03:00:00Z'::timestamptz),
  ('memahami-proteksi-pembeli', 'Memahami Proteksi Pembeli 14 & 30 Hari', 'Panduan', 'Setiap pesanan akun menyertakan proteksi Rp5.000 — ini yang sebenarnya kamu dapatkan dari biaya tersebut.', '/images/products/10.jpeg', '[{"type":"paragraph","text":"Setiap pembelian akun di valostock.id menyertakan biaya proteksi Rp5.000. Proteksi ini adalah jendela dukungan dan penanganan keamanan — tim kami siap membantu jika terjadi masalah seperti upaya penarikan kembali (recall) akun oleh pemilik lama."},{"type":"heading","text":"Durasi proteksi"},{"type":"list","items":["Akun dengan harga sampai Rp10 juta: jendela dukungan 14 hari.","Akun dengan harga di atas Rp10 juta: jendela dukungan 30 hari."]},{"type":"heading","text":"Yang perlu diluruskan"},{"type":"paragraph","text":"Proteksi bukan penahanan dana — pembayaran ke toko tetap cair 5 jam setelah akun dinyatakan aman. Proteksi juga bukan jaminan mutlak; ia adalah komitmen penanganan: kami menindaklanjuti laporanmu, memakai bukti dari Rekber Room, dan menegakkan sanksi ke toko yang terbukti bersalah, termasuk kompensasi dari deposit toko."},{"type":"paragraph","text":"Laporkan masalah sesegera mungkin melalui halaman pesananmu. Sengketa diproses dalam 72 jam dengan timeline yang bisa kamu pantau."}]'::jsonb, 'PUBLISHED', 'aba098e4-9d38-40ec-89ed-85c59e566191', '2026-06-20T03:00:00Z'::timestamptz, '2026-06-20T03:00:00Z'::timestamptz),
  ('store-premium-diluncurkan', 'Store Premium: Komisi Lebih Rendah untuk Toko Pro & Business', 'Pengumuman', 'Paket langganan untuk toko resmi meluncur — komisi turun hingga 4%, listing lebih banyak, dan slot featured gratis.', '/images/products/2.jpeg', '[{"type":"paragraph","text":"Untuk toko yang serius berjualan, kami meluncurkan Store Premium dengan dua paket: Pro (Rp99.000/bulan) dan Business (Rp299.000/bulan)."},{"type":"heading","text":"Perbandingan singkat"},{"type":"list","items":["Free: komisi 5%, hingga 15 listing aktif.","Pro: komisi 4,5%, hingga 60 listing, analytics, bulk upload, 2 slot featured gratis per bulan.","Business: komisi 4%, listing tanpa batas, analytics lanjutan, 6 slot featured gratis, prioritas dukungan & sengketa, akses API."]},{"type":"paragraph","text":"Perlu dicatat: Premium menurunkan komisi dan menambah kapasitas, tetapi tidak memengaruhi reputasi. Rating, Service Score, dan badge kepercayaan tetap harus diperoleh lewat transaksi yang baik — tidak bisa dibeli."},{"type":"paragraph","text":"Toko bisa berlangganan langsung dari dashboard di menu Subscription."}]'::jsonb, 'PUBLISHED', 'aba098e4-9d38-40ec-89ed-85c59e566191', '2026-06-15T03:00:00Z'::timestamptz, '2026-06-15T03:00:00Z'::timestamptz),
  ('tips-aman-membeli-akun', '5 Hal yang Perlu Dicek Sebelum Membeli Akun', 'Panduan', 'Dari badge toko sampai riwayat rating — checklist singkat supaya keputusan belimu lebih terinformasi.', '/images/products/3.jpeg', '[{"type":"paragraph","text":"Escrow dan proteksi melindungimu di sisi transaksi, tetapi keputusan memilih akun tetap di tanganmu. Berikut lima hal yang kami sarankan untuk selalu dicek."},{"type":"list","items":["Badge toko — Identity Verified menandakan identitas pemilik sudah diverifikasi admin; Verified dan Platinum mencerminkan rekam jejak; Deposit Secured berarti deposit keamanannya aktif.","Tipe toko — Owner Store menjual akun miliknya sendiri; Reseller Store menjual akun titipan penjual eksternal dan bertanggung jawab penuh atasnya.","Badge Account Checked — akun sudah diinspeksi dengan checklist dan bukti media.","Rating dan Service Score — lihat akurasi deskripsi, sikap layanan, dan kecepatan pengiriman dari pembeli sebelumnya.","Kelengkapan deskripsi — rank, koleksi skin, region, akses email, dan metode serah terima harus jelas sebelum kamu menawar."]},{"type":"paragraph","text":"Satu aturan emas terakhir: jangan pernah menyelesaikan transaksi di luar platform. Selain melanggar aturan, kamu kehilangan escrow, bukti Rekber Room, dan seluruh perlindungan yang menyertainya."}]'::jsonb, 'PUBLISHED', 'aba098e4-9d38-40ec-89ed-85c59e566191', '2026-06-10T03:00:00Z'::timestamptz, '2026-06-10T03:00:00Z'::timestamptz),
  ('loyalty-points-hadir', 'Kumpulkan Loyalty Points di Setiap Transaksi', 'Event & Promo', 'Setiap pembelian akun yang selesai kini menghasilkan poin — tukarkan dengan potongan harga di transaksi berikutnya.', '/images/products/4.jpeg', '[{"type":"paragraph","text":"Mulai bulan ini, setiap pesanan akun yang kamu selesaikan menghasilkan loyalty points. Poin terkumpul otomatis setelah kamu menekan Selesai dan memberi rating."},{"type":"heading","text":"Cara memakai poin"},{"type":"paragraph","text":"Poin bisa ditukarkan sebagai potongan harga saat checkout pembelian berikutnya. Saldo poin dan riwayatnya bisa kamu lihat di halaman Poin di area akunmu — setiap perolehan dan penukaran tercatat jelas."},{"type":"paragraph","text":"Program ini akan terus kami kembangkan, termasuk bonus poin untuk event tertentu. Pantau halaman Berita untuk pengumuman berikutnya."}]'::jsonb, 'PUBLISHED', 'aba098e4-9d38-40ec-89ed-85c59e566191', '2026-06-05T03:00:00Z'::timestamptz, '2026-06-05T03:00:00Z'::timestamptz),
  ('gabung-komunitas-discord', 'Gabung Komunitas valostock.id di Discord', 'Komunitas', 'Diskusi harga, info flash sale, dan pengumuman platform paling cepat — semuanya ada di server komunitas kami.', '/images/products/5.jpeg', '[{"type":"paragraph","text":"Server Discord komunitas valostock.id sudah dibuka. Di sana kamu bisa berdiskusi soal harga pasar akun, berbagi pengalaman, dan mendapat pengumuman platform lebih cepat."},{"type":"heading","text":"Satu hal penting"},{"type":"paragraph","text":"Discord, WhatsApp, dan Telegram hanya kami gunakan untuk notifikasi dan komunitas — bukan tempat bertransaksi. Semua penawaran, pembayaran, dan serah terima akun tetap terjadi di dalam platform melalui escrow dan Rekber Room. Waspadai siapa pun yang mengajakmu bertransaksi langsung lewat DM dan laporkan ke admin."},{"type":"paragraph","text":"Tautan undangan tersedia di footer situs. Sampai jumpa di sana!"}]'::jsonb, 'PUBLISHED', 'aba098e4-9d38-40ec-89ed-85c59e566191', '2026-06-01T03:00:00Z'::timestamptz, '2026-06-01T03:00:00Z'::timestamptz);
insert into public.banners (placement, title, subtitle, image, cta_label, link_url, sort_order, created_by) values
  ('HOME_HERO', 'Akun impianmu, dananya ditahan sampai kamu konfirmasi', 'Semua toko diverifikasi admin. Serah terima lewat Rekber Room yang diawasi admin.', '/images/Astra_--_TEASER_01.png', 'Jelajahi Akun', '/search', 0, 'aba098e4-9d38-40ec-89ed-85c59e566191'),
  ('HOME_HERO', 'Top-up VP, Diamond, dan Crystal', 'Bayar QRIS, Virtual Account, e-wallet, retail, atau Balance — struk langsung ke email.', '/images/Pride_2023.png', 'Top-Up Sekarang', '/topup', 1, 'aba098e4-9d38-40ec-89ed-85c59e566191');
insert into public.balance_ledger (user_id, type, amount, balance_after, reference) values
  ('dfd471ff-a0ab-42f9-8759-709231c59538', 'ADJUSTMENT', 100000, 100000, 'SEED-SALDO-AWAL');
